import React, { useState, useEffect, useRef } from "react";
import { ArrowLeftRight, RotateCcw, ChevronLeft, Plus, X, Trophy, Users } from "lucide-react";

const uid = () =>
  Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);

async function loadJSON(key, fallback) {
  try {
    const res = await window.storage.get(key, false);
    return res ? JSON.parse(res.value) : fallback;
  } catch (e) {
    return fallback;
  }
}
async function saveJSON(key, value) {
  try {
    const res = await window.storage.set(key, JSON.stringify(value), false);
    return !!res;
  } catch (e) {
    console.error("storage save failed", key, e);
    return false;
  }
}

function pppVal(pts, poss) {
  if (!poss) return null;
  return pts / poss;
}
function fmtPPP(v) {
  return v === null || v === undefined ? "—" : v.toFixed(2);
}
function todayStr() {
  return new Date().toISOString().slice(0, 10);
}
function fmtDate(d) {
  const dt = new Date(d + "T00:00:00");
  return dt.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}
function initials(name) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "—";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
}

// Possession counts per player, from the possession log (who was on the floor).
function computePossCounts(game) {
  const counts = {};
  for (const p of game.players) counts[p.id] = 0;
  for (const poss of game.possessions) {
    for (const id of poss.onCourt) {
      counts[id] = (counts[id] || 0) + 1;
    }
  }
  return counts;
}

function computeSeasonPlayerStats(games, roster) {
  const nameById = {};
  for (const r of roster) nameById[r.id] = { name: r.name, number: r.number };
  const agg = {};
  for (const g of games) {
    for (const p of g.players) {
      if (!nameById[p.id]) nameById[p.id] = { name: p.name, number: p.number };
    }
    const counts = computePossCounts(g);
    for (const [id, poss] of Object.entries(counts)) {
      if (!agg[id]) agg[id] = { poss: 0, pts: 0, games: 0 };
      if (poss > 0) agg[id].games += 1;
      agg[id].poss += poss;
      agg[id].pts += g.playerPoints?.[id] ?? 0;
    }
  }
  return Object.entries(agg)
    .map(([id, v]) => ({
      id,
      name: nameById[id]?.name || "Unknown",
      number: nameById[id]?.number || "",
      ...v,
      ppp: pppVal(v.pts, v.poss),
    }))
    .sort((a, b) => (b.ppp ?? -1) - (a.ppp ?? -1));
}
function computeSeasonTeamStats(games) {
  let poss = 0;
  let pts = 0;
  for (const g of games) {
    poss += g.possessions.length;
    pts += g.teamPointsAllowed ?? 0;
  }
  return { poss, pts, ppp: pppVal(pts, poss) };
}

const LOGO_SRC =
  "data:image/png;base64,";

function CrestBadge({ size = 44 }) {
  return (
    <img
      src={LOGO_SRC}
      alt="Team logo"
      className="ppp-crest"
      style={{ width: size, height: "auto", display: "block" }}
    />
  );
}

function CourtBacking() {
  return (
    <svg className="ppp-court" viewBox="0 0 440 140" preserveAspectRatio="none" aria-hidden="true">
      <rect x="1" y="1" width="438" height="138" fill="none" stroke="currentColor" strokeWidth="1.5" />
      <line x1="220" y1="1" x2="220" y2="139" stroke="currentColor" strokeWidth="1.5" />
      <circle cx="220" cy="70" r="30" fill="none" stroke="currentColor" strokeWidth="1.5" />
      <path d="M 1 32 L 65 32 L 65 108 L 1 108" fill="none" stroke="currentColor" strokeWidth="1.5" />
      <path d="M 439 32 L 375 32 L 375 108 L 439 108" fill="none" stroke="currentColor" strokeWidth="1.5" />
      <path d="M 1 10 A 165 165 0 0 1 1 130" fill="none" stroke="currentColor" strokeWidth="1.5" />
      <path d="M 439 10 A 165 165 0 0 0 439 130" fill="none" stroke="currentColor" strokeWidth="1.5" />
    </svg>
  );
}

function GameRow({ game, onClick }) {
  return (
    <button className="ppp-row-btn" onClick={onClick}>
      <span className="ppp-row-main">
        <span className="ppp-mono">{initials(game.opponent)}</span>
        <span className="ppp-row-text">
          <span className="ppp-row-opp">vs {game.opponent}</span>
          <span className="ppp-dim">{fmtDate(game.date)}</span>
        </span>
      </span>
      <span className={`ppp-tag ${game.final ? "" : "is-live"}`}>
        {game.final ? "Final" : "Live"}
      </span>
    </button>
  );
}

function LineupEditor({ onCourt, players, onChange }) {
  return (
    <div className="ppp-lineup-editor">
      {onCourt.map((pid, idx) => {
        const options = players.filter((p) => p.id === pid || !onCourt.includes(p.id));
        return (
          <select
            key={idx}
            className="ppp-select"
            value={pid}
            onChange={(e) => {
              const next = [...onCourt];
              next[idx] = e.target.value;
              onChange(next);
            }}
          >
            {options.map((p) => (
              <option key={p.id} value={p.id}>
                {p.number ? `#${p.number} ` : ""}
                {p.name}
              </option>
            ))}
          </select>
        );
      })}
    </div>
  );
}

export default function App() {
  const [ready, setReady] = useState(false);
  const [roster, setRoster] = useState([]);
  const [gamesIndex, setGamesIndex] = useState([]);
  const [screen, setScreen] = useState("home");
  const [activeGame, setActiveGame] = useState(null);
  const [subPick, setSubPick] = useState(null);
  const [seasonData, setSeasonData] = useState(null);
  const [viewGame, setViewGame] = useState(null);
  const [newGameForm, setNewGameForm] = useState({
    opponent: "",
    date: todayStr(),
    selected: [],
    starters: [],
  });
  const [rosterForm, setRosterForm] = useState({ name: "", number: "" });
  const [notice, setNotice] = useState(null);
  const [heroPPP, setHeroPPP] = useState(undefined);

  useEffect(() => {
    (async () => {
      const r = await loadJSON("roster", []);
      const gi = await loadJSON("games-index", []);
      setRoster(r);
      setGamesIndex(gi);
      setReady(true);
    })();
  }, []);

  useEffect(() => {
    if (!ready) return;
    const finalGame = gamesIndex.find((g) => g.final);
    if (!finalGame) {
      setHeroPPP(null);
      return;
    }
    (async () => {
      const g = await loadJSON(`game:${finalGame.id}`, null);
      if (!g) return setHeroPPP(null);
      const poss = g.possessions.length;
      const pts = g.teamPointsAllowed;
      setHeroPPP(pts === undefined ? null : pppVal(pts, poss));
    })();
  }, [ready, gamesIndex]);

  const flash = (msg, isError) => {
    setNotice({ msg, isError: !!isError });
    if (!isError) setTimeout(() => setNotice(null), 2000);
  };

  // ---------- roster ----------
  const addPlayer = async () => {
    const name = rosterForm.name.trim();
    if (!name) return;
    const p = { id: uid(), name, number: rosterForm.number.trim() };
    const next = [...roster, p];
    setRoster(next);
    setRosterForm({ name: "", number: "" });
    const ok = await saveJSON("roster", next);
    if (!ok) flash("Couldn't save roster change.", true);
  };
  const removePlayer = async (id) => {
    const next = roster.filter((p) => p.id !== id);
    setRoster(next);
    const ok = await saveJSON("roster", next);
    if (!ok) flash("Couldn't save roster change.", true);
  };

  // ---------- new game ----------
  const toggleSelected = (id) => {
    setNewGameForm((f) => {
      const has = f.selected.includes(id);
      const selected = has ? f.selected.filter((x) => x !== id) : [...f.selected, id];
      const starters = f.starters.filter((x) => selected.includes(x));
      return { ...f, selected, starters };
    });
  };
  const toggleStarter = (id) => {
    setNewGameForm((f) => {
      const has = f.starters.includes(id);
      if (has) return { ...f, starters: f.starters.filter((x) => x !== id) };
      if (f.starters.length >= 5) return f;
      return { ...f, starters: [...f.starters, id] };
    });
  };
  const startGame = async () => {
    const { opponent, date, selected, starters } = newGameForm;
    if (!opponent.trim() || starters.length !== 5) return;
    const players = roster
      .filter((p) => selected.includes(p.id))
      .map((p) => ({ id: p.id, name: p.name, number: p.number }));
    const game = {
      id: uid(),
      opponent: opponent.trim(),
      date,
      players,
      onCourt: [...starters],
      possessions: [],
      playerPoints: {},
      teamPointsAllowed: undefined,
      final: false,
      createdAt: Date.now(),
    };
    const ok = await saveJSON(`game:${game.id}`, game);
    const nextIndex = [
      { id: game.id, opponent: game.opponent, date: game.date, final: false },
      ...gamesIndex,
    ];
    setGamesIndex(nextIndex);
    await saveJSON("games-index", nextIndex);
    setActiveGame(game);
    setNewGameForm({ opponent: "", date: todayStr(), selected: [], starters: [] });
    if (!ok) flash("Game started, but the save failed — check connection.", true);
    setScreen("live");
  };

  // ---------- live game ----------
  const persist = async (game) => {
    const ok = await saveJSON(`game:${game.id}`, game);
    if (!ok) flash("Last change didn't save — check connection.", true);
    else if (notice?.isError) setNotice(null);
  };
  const logPossession = async () => {
    if (!activeGame) return;
    const entry = { onCourt: [...activeGame.onCourt], ts: Date.now() };
    const next = { ...activeGame, possessions: [...activeGame.possessions, entry] };
    setActiveGame(next);
    await persist(next);
  };
  const undoPossession = async () => {
    if (!activeGame || activeGame.possessions.length === 0) return;
    const next = { ...activeGame, possessions: activeGame.possessions.slice(0, -1) };
    setActiveGame(next);
    await persist(next);
  };
  const fixPossessionLineup = async (index, newOnCourt) => {
    if (!activeGame) return;
    const possessions = activeGame.possessions.map((p, i) =>
      i === index ? { ...p, onCourt: newOnCourt } : p
    );
    const next = { ...activeGame, possessions };
    setActiveGame(next);
    await persist(next);
  };
  const doSub = async (outId, inId) => {
    if (!activeGame) return;
    const onCourt = activeGame.onCourt.map((id) => (id === outId ? inId : id));
    const next = { ...activeGame, onCourt };
    setActiveGame(next);
    setSubPick(null);
    await persist(next);
  };
  const endGame = async () => {
    if (!activeGame) return;
    const next = { ...activeGame, final: true };
    setActiveGame(next);
    await persist(next);
    const nextIndex = gamesIndex.map((g) => (g.id === next.id ? { ...g, final: true } : g));
    setGamesIndex(nextIndex);
    await saveJSON("games-index", nextIndex);
    setScreen("summary");
  };
  const resumeGame = async (id) => {
    const g = await loadJSON(`game:${id}`, null);
    if (g) {
      setActiveGame(g);
      setScreen(g.final ? "summary" : "live");
    }
  };

  // ---------- season ----------
  const openSeason = async () => {
    setScreen("season");
    setSeasonData(null);
    const all = [];
    for (const g of gamesIndex) {
      const full = await loadJSON(`game:${g.id}`, null);
      if (full) all.push(full);
    }
    setSeasonData(all);
  };
  const openGameView = async (id) => {
    const g = await loadJSON(`game:${id}`, null);
    setViewGame(g);
    setScreen("gameview");
  };

  if (!ready) {
    return (
      <div className="ppp-app">
        <Style />
        <div className="ppp-loading">Loading tracker…</div>
      </div>
    );
  }

  const unfinished = gamesIndex.find((g) => !g.final);

  return (
    <div className="ppp-app">
      <Style />
      {screen === "home" ? (
        <header className="ppp-header">
          <div className="ppp-header-center">
            <CrestBadge size={92} />
            <span className="ppp-brand">Saint Mary&rsquo;s</span>
            <h1>Possession Tracker</h1>
          </div>
        </header>
      ) : (
        <header className="ppp-topbar">
          <div className="ppp-topbar-inner">
            <button
              className="ppp-back"
              onClick={() => {
                setScreen("home");
                setSubPick(null);
              }}
            >
              <ChevronLeft size={18} /> Home
            </button>
            <div className="ppp-topbar-brand">
              <CrestBadge size={26} />
              <span className="ppp-topbar-text">
                Saint Mary&rsquo;s <span className="ppp-dim">· Possession Tracker</span>
              </span>
            </div>
            <span className="ppp-topbar-spacer" />
          </div>
        </header>
      )}

      {notice && (
        <div className={`ppp-notice ${notice.isError ? "is-error" : ""}`}>{notice.msg}</div>
      )}

      {screen === "home" && (
        <div className="ppp-stack">
          <div className="ppp-hero">
            <CourtBacking />
            <div className="ppp-hero-inner">
              <div className="ppp-hero-primary">
                <div className="ppp-hero-primary-label">Last Game PPP Allowed</div>
                <div className="ppp-hero-primary-num">
                  {heroPPP === undefined ? "…" : fmtPPP(heroPPP)}
                </div>
              </div>
              <div className="ppp-hero-divider" />
              <div className="ppp-hero-secondary">
                <div className="ppp-hero-sec-row">
                  <span className="ppp-hero-sec-num">{gamesIndex.length}</span>
                  <span className="ppp-hero-sec-label">Games Logged</span>
                </div>
                <div className="ppp-hero-sec-row">
                  <span className="ppp-hero-sec-num">
                    {gamesIndex.filter((g) => g.final).length}
                  </span>
                  <span className="ppp-hero-sec-label">Final</span>
                </div>
              </div>
            </div>
          </div>

          {unfinished && (
            <button className="ppp-banner" onClick={() => resumeGame(unfinished.id)}>
              <span className="ppp-banner-live">
                <span className="ppp-live-dot" />
                Live
              </span>
              <span className="ppp-banner-text">
                vs {unfinished.opponent} <span className="ppp-dim">· {fmtDate(unfinished.date)}</span>
              </span>
              <span className="ppp-banner-cta">Resume →</span>
            </button>
          )}

          <div className="ppp-menu">
            <button
              className="ppp-menu-feature"
              onClick={() => setScreen(roster.length ? "newgame" : "roster")}
            >
              <div className="ppp-menu-feature-icon">
                <Plus size={22} />
              </div>
              <div>
                <div className="ppp-menu-title">New Game</div>
                <div className="ppp-menu-sub">Track possessions live, courtside</div>
              </div>
            </button>
            <div className="ppp-menu-row">
              <button className="ppp-menu-tile" onClick={openSeason}>
                <Trophy size={18} />
                <div className="ppp-menu-tile-title">Season Stats</div>
                <div className="ppp-menu-tile-sub">PPP by player</div>
              </button>
              <button className="ppp-menu-tile" onClick={() => setScreen("roster")}>
                <Users size={18} />
                <div className="ppp-menu-tile-title">Roster</div>
                <div className="ppp-menu-tile-sub">{roster.length} players</div>
              </button>
            </div>
          </div>

          {gamesIndex.length > 0 && (
            <div className="ppp-panel">
              <div className="ppp-panel-title">Games</div>
              <div className="ppp-help">Tap any final game to edit its points allowed later.</div>
              <div className="ppp-list">
                {gamesIndex.map((g) => (
                  <GameRow
                    key={g.id}
                    game={g}
                    onClick={() => (g.final ? openGameView(g.id) : resumeGame(g.id))}
                  />
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {screen === "roster" && (
        <div className="ppp-stack">
          <div className="ppp-panel">
            <div className="ppp-panel-title">Add a player</div>
            <div className="ppp-form-row">
              <input
                className="ppp-input"
                placeholder="Name"
                value={rosterForm.name}
                onChange={(e) => setRosterForm((f) => ({ ...f, name: e.target.value }))}
                onKeyDown={(e) => e.key === "Enter" && addPlayer()}
              />
              <input
                className="ppp-input ppp-input-num"
                placeholder="#"
                value={rosterForm.number}
                onChange={(e) => setRosterForm((f) => ({ ...f, number: e.target.value }))}
                onKeyDown={(e) => e.key === "Enter" && addPlayer()}
              />
              <button className="ppp-btn" onClick={addPlayer}>
                Add
              </button>
            </div>
          </div>
          <div className="ppp-panel">
            <div className="ppp-panel-title">Roster ({roster.length})</div>
            {roster.length === 0 && (
              <div className="ppp-empty">No players yet. Add your roster above.</div>
            )}
            <div className="ppp-list">
              {roster.map((p) => (
                <div key={p.id} className="ppp-row-btn ppp-row-static">
                  <span>
                    {p.number && <span className="ppp-num">#{p.number}</span>} {p.name}
                  </span>
                  <button className="ppp-icon-btn" onClick={() => removePlayer(p.id)} aria-label="Remove">
                    <X size={16} />
                  </button>
                </div>
              ))}
            </div>
          </div>
          {roster.length > 0 && (
            <button className="ppp-btn primary full" onClick={() => setScreen("newgame")}>
              Continue to New Game
            </button>
          )}
        </div>
      )}

      {screen === "newgame" && (
        <div className="ppp-stack">
          <div className="ppp-panel">
            <div className="ppp-panel-title">Matchup</div>
            <div className="ppp-form-row">
              <input
                className="ppp-input"
                placeholder="Opponent"
                value={newGameForm.opponent}
                onChange={(e) => setNewGameForm((f) => ({ ...f, opponent: e.target.value }))}
              />
              <input
                className="ppp-input ppp-input-date"
                type="date"
                value={newGameForm.date}
                onChange={(e) => setNewGameForm((f) => ({ ...f, date: e.target.value }))}
              />
            </div>
          </div>

          <div className="ppp-panel">
            <div className="ppp-panel-title">Active for this game</div>
            <div className="ppp-chip-grid">
              {roster.map((p) => (
                <button
                  key={p.id}
                  className={`ppp-chip ${newGameForm.selected.includes(p.id) ? "is-on" : ""}`}
                  onClick={() => toggleSelected(p.id)}
                >
                  {p.number && <span className="ppp-num">#{p.number}</span>} {p.name}
                </button>
              ))}
            </div>
          </div>

          {newGameForm.selected.length >= 2 && (
            <div className="ppp-panel">
              <div className="ppp-panel-title">
                Starting 5 <span className="ppp-dim">({newGameForm.starters.length}/5)</span>
              </div>
              <div className="ppp-chip-grid">
                {roster
                  .filter((p) => newGameForm.selected.includes(p.id))
                  .map((p) => (
                    <button
                      key={p.id}
                      className={`ppp-chip ${newGameForm.starters.includes(p.id) ? "is-on" : ""}`}
                      onClick={() => toggleStarter(p.id)}
                    >
                      {p.number && <span className="ppp-num">#{p.number}</span>} {p.name}
                    </button>
                  ))}
              </div>
            </div>
          )}

          <button
            className="ppp-btn primary full"
            disabled={!newGameForm.opponent.trim() || newGameForm.starters.length !== 5}
            onClick={startGame}
          >
            Start Game
          </button>
        </div>
      )}

      {screen === "live" && activeGame && (
        <LiveGame
          game={activeGame}
          subPick={subPick}
          setSubPick={setSubPick}
          onLog={logPossession}
          onUndo={undoPossession}
          onSub={doSub}
          onFixLineup={fixPossessionLineup}
          onEnd={endGame}
        />
      )}

      {screen === "summary" && activeGame && (
        <GameSummary
          game={activeGame}
          onChange={async (g) => {
            setActiveGame(g);
            await persist(g);
          }}
          onDone={() => setScreen("home")}
        />
      )}

      {screen === "gameview" && viewGame && (
        <GameSummary
          game={viewGame}
          onChange={async (g) => {
            setViewGame(g);
            await saveJSON(`game:${g.id}`, g);
          }}
          onDone={() => setScreen("home")}
          label="Game Detail"
        />
      )}

      {screen === "season" && (
        <SeasonView data={seasonData} onOpenGame={openGameView} gamesIndex={gamesIndex} />
      )}
    </div>
  );
}

function LiveGame({ game, subPick, setSubPick, onLog, onUndo, onSub, onFixLineup, onEnd }) {
  const byId = Object.fromEntries(game.players.map((p) => [p.id, p]));
  const bench = game.players.filter((p) => !game.onCourt.includes(p.id));
  const counts = computePossCounts(game);
  const rows = game.players
    .map((p) => ({ ...p, poss: counts[p.id] || 0 }))
    .sort((a, b) => b.poss - a.poss);
  const teamPoss = game.possessions.length;
  const recent = game.possessions
    .map((p, i) => ({ ...p, index: i }))
    .slice(-5)
    .reverse();

  return (
    <div className="ppp-stack">
      <div className="ppp-live-top">
        <div>
          <div className="ppp-dim">
            vs {game.opponent} · {fmtDate(game.date)}
          </div>
          <div className="ppp-teamline">
            <span className="ppp-big">{teamPoss}</span>
            <span className="ppp-dim">team possessions</span>
          </div>
        </div>
        <button className="ppp-btn danger" onClick={onEnd}>
          End Game
        </button>
      </div>

      <div className="ppp-panel ppp-court-panel">
        <div className="ppp-panel-title">On Court</div>
        <div className="ppp-court-wrap">
          <CourtBacking />
          <div className="ppp-oncourt-row">
            {game.onCourt.map((id) => {
              const p = byId[id];
              if (!p) return null;
              return (
                <button
                  key={id}
                  className={`ppp-player-chip ${subPick ? "is-target" : ""}`}
                  onClick={() => subPick && onSub(id, subPick)}
                >
                  {p.number && <span className="ppp-num">#{p.number}</span>}
                  <span>{p.name}</span>
                </button>
              );
            })}
          </div>
        </div>
        {subPick && (
          <div className="ppp-sub-hint">
            <ArrowLeftRight size={14} /> Tap a player on court to sub in {byId[subPick]?.name}
            <button className="ppp-link" onClick={() => setSubPick(null)}>
              cancel
            </button>
          </div>
        )}
        <div className="ppp-panel-title" style={{ marginTop: "14px" }}>
          Bench
        </div>
        <div className="ppp-chip-grid">
          {bench.map((p) => (
            <button
              key={p.id}
              className={`ppp-chip ${subPick === p.id ? "is-on" : ""}`}
              onClick={() => setSubPick(subPick === p.id ? null : p.id)}
            >
              {p.number && <span className="ppp-num">#{p.number}</span>} {p.name}
            </button>
          ))}
          {bench.length === 0 && (
            <div className="ppp-empty">Everyone active is on the floor.</div>
          )}
        </div>
      </div>

      <div className="ppp-panel">
        <div className="ppp-panel-title">Track Possessions</div>
        <div className="ppp-help">Tap once each time this possession ends. Points allowed get entered after the game.</div>
        <button className="ppp-log-btn" onClick={onLog}>
          + Log Possession
        </button>
        <button className="ppp-btn ghost" onClick={onUndo} disabled={game.possessions.length === 0}>
          <RotateCcw size={15} /> Undo last possession
        </button>

        {recent.length > 0 && (
          <div className="ppp-recent-wrap">
            <div className="ppp-panel-title" style={{ marginTop: "16px", marginBottom: "8px" }}>
              Recent — fix a credit
            </div>
            <div className="ppp-help">
              If someone got subbed mid-possession, swap the outgoing player for whoever finished it.
            </div>
            {recent.map((p) => (
              <div key={p.index} className="ppp-recent-row">
                <span className="ppp-poss-index">#{p.index + 1}</span>
                <LineupEditor
                  onCourt={p.onCourt}
                  players={game.players}
                  onChange={(next) => onFixLineup(p.index, next)}
                />
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="ppp-panel">
        <div className="ppp-panel-title">Possessions on Floor</div>
        <div className="ppp-table">
          <div className="ppp-table-head ppp-table-head-2col">
            <span>Player</span>
            <span>Poss</span>
          </div>
          {rows.map((r) => (
            <div key={r.id} className="ppp-table-row ppp-table-row-2col">
              <span>
                {r.number && <span className="ppp-num">#{r.number}</span>} {r.name}
              </span>
              <span>{r.poss}</span>
            </div>
          ))}
          {rows.length === 0 && <div className="ppp-empty">No possessions logged yet.</div>}
        </div>
      </div>
    </div>
  );
}

function GameSummary({ game, onChange, onDone, label }) {
  const [teamPts, setTeamPts] = useState(game.teamPointsAllowed);
  const [playerPts, setPlayerPts] = useState(game.playerPoints || {});
  const saveTimer = useRef(null);
  const latestRef = useRef(null);
  latestRef.current = { game, teamPts, playerPts };

  // Only re-sync from the prop when we're looking at a different game.
  useEffect(() => {
    setTeamPts(game.teamPointsAllowed);
    setPlayerPts(game.playerPoints || {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [game.id]);

  useEffect(() => {
    return () => {
      if (saveTimer.current) clearTimeout(saveTimer.current);
      const { game: g, teamPts: tp, playerPts: pp } = latestRef.current;
      onChange({ ...g, teamPointsAllowed: tp, playerPoints: pp });
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const scheduleSave = (patch) => {
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => {
      onChange({ ...game, ...patch });
      saveTimer.current = null;
    }, 600);
  };
  const flushSave = () => {
    if (saveTimer.current) {
      clearTimeout(saveTimer.current);
      saveTimer.current = null;
    }
    onChange({ ...game, teamPointsAllowed: teamPts, playerPoints: playerPts });
  };

  const handleTeamChange = (val) => {
    const num = val === "" ? undefined : Math.max(0, Number(val));
    setTeamPts(num);
    scheduleSave({ teamPointsAllowed: num });
  };
  const handlePlayerChange = (id, val) => {
    const next = { ...playerPts };
    if (val === "") delete next[id];
    else next[id] = Math.max(0, Number(val));
    setPlayerPts(next);
    scheduleSave({ playerPoints: next });
  };
  const handleDone = () => {
    flushSave();
    onDone();
  };

  const counts = computePossCounts(game);
  const teamPoss = game.possessions.length;
  const teamPPP = teamPts === undefined ? null : pppVal(teamPts, teamPoss);

  // Fixed order (roster order the game was set up with) — never re-sorted,
  // so a row doesn't jump around under your cursor while you're typing.
  const rows = game.players.map((p) => {
    const poss = counts[p.id] || 0;
    const pts = playerPts[p.id] ?? 0;
    return { ...p, poss, pts, ppp: pppVal(pts, poss) };
  });

  return (
    <div className="ppp-stack">
      <div className="ppp-panel">
        <div className="ppp-panel-title">{label || "Final"}</div>
        <div className="ppp-summary-head">
          <div className="ppp-dim">
            vs {game.opponent} · {fmtDate(game.date)}
          </div>
        </div>

        <div className="ppp-team-row">
          <div>
            <div className="ppp-field-label">Team points allowed</div>
            <input
              className="ppp-input ppp-num-input"
              type="number"
              min="0"
              inputMode="numeric"
              placeholder="0"
              value={teamPts ?? ""}
              onChange={(e) => handleTeamChange(e.target.value)}
              onBlur={flushSave}
            />
          </div>
          <div className="ppp-team-computed">
            <div className="ppp-dim">{teamPoss} team possessions</div>
            <div className="ppp-big">{fmtPPP(teamPPP)}</div>
            <div className="ppp-dim">team PPP</div>
          </div>
        </div>
      </div>

      <div className="ppp-panel">
        <div className="ppp-panel-title">Points Allowed Per Player</div>
        <div className="ppp-help">
          Enter what each player gave up; PPP updates as you type. Come back anytime to fix a number.
        </div>
        <div className="ppp-player-points-table">
          <div className="ppp-pp-head">
            <span>Player</span>
            <span>Poss</span>
            <span>Pts</span>
            <span>PPP</span>
          </div>
          {rows.map((r) => (
            <div key={r.id} className="ppp-pp-row">
              <span>
                {r.number && <span className="ppp-num">#{r.number}</span>} {r.name}
              </span>
              <span className="ppp-pp-poss">{r.poss}</span>
              <input
                className="ppp-input ppp-num-input"
                type="number"
                min="0"
                inputMode="numeric"
                placeholder="0"
                value={playerPts[r.id] ?? ""}
                onChange={(e) => handlePlayerChange(r.id, e.target.value)}
                onBlur={flushSave}
              />
              <span className="ppp-ppp-cell">{fmtPPP(r.ppp)}</span>
            </div>
          ))}
          {rows.length === 0 && <div className="ppp-empty">No players were set for this game.</div>}
        </div>
      </div>

      <button className="ppp-btn primary full" onClick={handleDone}>
        Back to Home
      </button>
    </div>
  );
}

function SeasonView({ data, onOpenGame, gamesIndex }) {
  if (data === null) {
    return (
      <div className="ppp-stack">
        <div className="ppp-empty">Loading season data…</div>
      </div>
    );
  }
  const rows = computeSeasonPlayerStats(data, data.flatMap((g) => g.players)).filter(
    (r) => r.poss > 0
  );
  const team = computeSeasonTeamStats(data);

  return (
    <div className="ppp-stack">
      <div className="ppp-panel">
        <div className="ppp-panel-title">
          Season PPP <span className="ppp-dim">({data.length} game{data.length === 1 ? "" : "s"})</span>
        </div>
        <div className="ppp-teamline" style={{ marginBottom: "12px" }}>
          <span className="ppp-big">{fmtPPP(team.ppp)}</span>
          <span className="ppp-dim">team PPP ({team.pts} pts / {team.poss} poss)</span>
        </div>
        <div className="ppp-table">
          <div className="ppp-table-head">
            <span>Player</span>
            <span>GP</span>
            <span>Poss</span>
            <span>Pts</span>
            <span>PPP</span>
          </div>
          {rows.map((r) => (
            <div key={r.id} className="ppp-table-row ppp-table-row-5">
              <span>
                {r.number && <span className="ppp-num">#{r.number}</span>} {r.name}
              </span>
              <span>{r.games}</span>
              <span>{r.poss}</span>
              <span>{r.pts}</span>
              <span className="ppp-ppp-cell">{fmtPPP(r.ppp)}</span>
            </div>
          ))}
          {rows.length === 0 && <div className="ppp-empty">No games saved yet.</div>}
        </div>
      </div>

      <div className="ppp-panel">
        <div className="ppp-panel-title">Games</div>
        <div className="ppp-list">
          {gamesIndex.map((g) => (
            <GameRow key={g.id} game={g} onClick={() => onOpenGame(g.id)} />
          ))}
        </div>
      </div>
    </div>
  );
}

